// Ported from the Node app's Sequelize model GradingSetting (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class GradingSettingConfiguration : IEntityTypeConfiguration<GradingSetting>
{
    public void Configure(EntityTypeBuilder<GradingSetting> builder)
    {
        builder.ToTable("grading_settings");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").ValueGeneratedNever();
        builder.Property(e => e.PassPercent).HasColumnName("pass_percent").HasColumnType("decimal(5,2)");
    }
}
